import{_ as s,C as r,o as i,c,a2 as a,j as t,G as n}from"./chunks/framework.BgSoyxN5.js";const T=JSON.parse('{"title":"Ротация секторов: лидерство, а не просто зелёные свечи | TickerForge","description":"Как отделить сектора, которые действительно ведут рынок, от тех, что растут вместе со всеми: две оси — абсолютный тренд и относительная динамика. На что отвечает и как публиковать это в канале.","frontmatter":{"title":"Ротация секторов: лидерство, а не просто зелёные свечи | TickerForge","description":"Как отделить сектора, которые действительно ведут рынок, от тех, что растут вместе со всеми: две оси — абсолютный тренд и относительная динамика. На что отвечает и как публиковать это в канале.","aside":false,"locale":"ru","alternateLocales":{"en":"/market-intelligence/sector-rotation","ru":"/ru/market-intelligence/sector-rotation"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/market-intelligence/sector-rotation.md","filePath":"ru/market-intelligence/sector-rotation.md","lastUpdated":1788410450000}'),h={name:"ru/market-intelligence/sector-rotation.md"},p={class:"partners-wide"},d={class:"partners-post-gallery"};function m(g,e,u,_,k,f){const o=r("PartnerPostImage"),l=r("PartnerChannelCta");return i(),c("div",null,[e[0]||(e[0]=a('<h1 id="ротация-секторов" tabindex="-1">Ротация секторов <a class="header-anchor" href="#ротация-секторов" aria-label="Permalink to &quot;Ротация секторов&quot;">​</a></h1><p>«Технологии выросли сегодня» — это не лидерство. Сегодня выросло всё. Полезный вопрос в том, какие сектора выросли <em>сильнее рынка</em> и новое ли это.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="/methodology/sector-rotation">Как это измеряется</a><a class="partners-button partners-button--secondary" href="#publish">Публиковать в своём канале</a></div><p class="partners-locale-switch"><a href="/market-intelligence/sector-rotation" hreflang="en">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a> · <a href="/ru/market-intelligence/market-regime">Рыночный режим</a> · <a href="/ru/market-intelligence/market-stress">Рыночный стресс</a></p><h2 id="answers" tabindex="-1">На какой вопрос отвечает <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;На какой вопрос отвечает {#answers}&quot;">​</a></h2><p><strong>«Куда на самом деле сместилось лидерство — и смена ли это?»</strong></p><p>В сильный день зелёные почти все сектора, и лента с топом движений просто пересказывает рынок дважды. Ротация — про относительное поведение: какой сектор ушёл вперёд индекса, какой отстал и отличается ли порядок от прошлой недели.</p><h2 id="why" tabindex="-1">Почему две оси сильнее рейтинга <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Почему две оси сильнее рейтинга {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Абсолютный тренд и относительная динамика измеряются отдельно.</strong> Сектор может расти и одновременно сдавать позиции. Одномерный рейтинг такое выразить не может, две оси — могут, и обычно это самое интересное состояние.</li><li><strong>Событие — это смена лидерства.</strong> Чтение построено так, чтобы показывать, где сдвинулся порядок, а не повторять, что рынок вырос.</li><li><strong>Тактика и структура — разные посты.</strong> Дневной взгляд отвечает, что двигалось на этой неделе; недельный — изменилась ли структура. Когда их смешивают, канал начинает называть ротацией каждое колебание.</li><li><strong>Полезнее всего под режимом.</strong> Защитное лидерство внутри <a href="/ru/market-intelligence/market-regime">режима Восстановления</a> — противоречие, о котором стоит написать. Ни одно чтение по отдельности его не покажет.</li></ul></div><h2 id="example" tabindex="-1">Как выглядит пост <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Как выглядит пост {#example}&quot;">​</a></h2>',11)),t("div",p,[t("div",d,[n(o,{src:"/partners/examples/sector-rotation-sample.png",alt:"Пост TickerForge «Ротация секторов»: какие сектора вели рынок, какие отставали и где сменилось лидерство",caption:"Кто вёл, кто отставал и что изменилось с прошлого раза.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">Как это считается <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Как это считается {#method}&quot;">​</a></h2><p>Две оси: направление абсолютного тренда каждого сектора и динамика относительно широкого индекса. Позиция сектора — это пара значений, и именно она отделяет «растёт» от «ведёт».</p><p>Полное описание: <a href="/methodology/sector-rotation">Sector rotation methodology</a>.</p><h2 id="publish" tabindex="-1">Два способа этим пользоваться <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Два способа этим пользоваться {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Читать.</strong> Посты по ротации секторов выходят в публичном канале TickerForge в дневной и недельной форме.</li><li><strong>Публиковать.</strong> Ротация секторов доступна для партнёрских пилотов — напишите об этом на странице <a href="/ru/partners/market-news">рыночных новостей</a>: мы приоритизируем по тому, что партнёры реально просят.</li></ul></div>',5)),n(l),e[2]||(e[2]=a('<p>Ротация — это контекст, а не сигнал. Лидерство описывает то, что уже произошло между секторами, и не является указанием перекладывать портфель. TickerForge — образовательное ПО для поддержки решений, не инвестиционная рекомендация.</p><h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a></li><li><a href="/methodology/sector-rotation">Методология ротации секторов</a></li><li><a href="/ru/market-intelligence/market-regime">Рыночный режим</a></li><li><a href="/ru/partners/market-news">Партнёрская программа по рыночным новостям</a></li></ul>',3))])}const P=s(h,[["render",m]]);export{T as __pageData,P as default};
